"""Batch job runner migrated from Meridian CRM 4.2 semantics."""

from typing import Any, Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], Any]) -> list[dict]:
    """Run scheduled jobs sequentially using their configured error policies.

    The executor is invoked once per attempt and may raise any Exception to
    indicate failure. Job failures are recorded in the returned log and never
    propagated by this runner.
    """
    run_log: list[dict] = []

    for job in jobs:
        on_error = job["on_error"]
        policy = on_error["policy"]
        retries = on_error["retries"] if policy == "RETRY" else 0
        attempts = 0

        while attempts <= retries:
            attempts += 1
            try:
                executor(job)
            except Exception:
                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                if policy == "RETRY" and attempts <= retries:
                    continue

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
